// Note: OpenProject's API key for this integration lacks permission to list/search
// all users (403 on /api/v3/users), so name-to-ID resolution can't be done live.
// Add teammates here as needed.
const USER_NAME_TO_ID = {
  'đàm quốc khánh': 21,
  'dam quoc khanh': 21,
  'khanh': 21,
};

const input = $input.first().json || {};
const overrideUserName = input['OpenProject User Name'];
const overrideDate = input['Reference Date (YYYY-MM-DD)'];

const userName = (overrideUserName && overrideUserName.trim() !== '') ? overrideUserName.trim() : 'Đàm Quốc Khánh';
const normalizedName = userName.toLowerCase();
const userId = USER_NAME_TO_ID[normalizedName];
if (!userId) {
  throw new Error(`Unknown user name "${userName}". Add it to USER_NAME_TO_ID in this node's code.`);
}

const now = (overrideDate && overrideDate !== '') ? new Date(overrideDate + 'T00:00:00') : new Date();

const day = now.getDay();
const diffToMonday = day === 0 ? -6 : 1 - day;
const monday = new Date(now);
monday.setDate(now.getDate() + diffToMonday);
monday.setHours(0, 0, 0, 0);
const friday = new Date(monday);
friday.setDate(monday.getDate() + 4);

function fmtShort(d) {
  const dd = String(d.getDate()).padStart(2, '0');
  const mm = String(d.getMonth() + 1).padStart(2, '0');
  return `${dd}/${mm}`;
}
// Format in local time (GENERIC_TIMEZONE); toISOString() would convert to UTC and shift the date back a day in UTC+7.
function fmtISO(d) {
  const yyyy = d.getFullYear();
  const mm = String(d.getMonth() + 1).padStart(2, '0');
  const dd = String(d.getDate()).padStart(2, '0');
  return `${yyyy}-${mm}-${dd}`;
}
function getWeekNumber(d) {
  const date = new Date(Date.UTC(d.getFullYear(), d.getMonth(), d.getDate()));
  date.setUTCDate(date.getUTCDate() + 4 - (date.getUTCDay() || 7));
  const yearStart = new Date(Date.UTC(date.getUTCFullYear(), 0, 1));
  return Math.ceil((((date - yearStart) / 86400000) + 1) / 7);
}

const weekNumber = getWeekNumber(monday);
const year = monday.getFullYear();
const saturday = new Date(friday);
saturday.setDate(friday.getDate() + 1);

return [{
  json: {
    userId,
    userName,
    mondayDate: fmtISO(monday),
    fridayDate: fmtISO(friday),
    filterEndDate: fmtISO(saturday),
    cardTitle: `${fmtShort(monday)} - ${fmtShort(friday)}/${year}`,
    weekNumber,
    year
  }
}];

const d = $input.first().json;
const b64 = Buffer.from(`apikey:${$env.OPENPROJECT_API_KEY}`).toString('base64');
// OpenProject filters are AND-only, so fetch assigned and accountable (responsible) tasks separately and merge later.
const updatedAt = { updatedAt: { operator: '<>d', values: [d.mondayDate, d.filterEndDate] } };
return ['assignee', 'responsible'].map(field => ({
  json: {
    ...d,
    role: field,
    filters: JSON.stringify([{ [field]: { operator: '=', values: [String(d.userId)] } }, updatedAt]),
    authHeader: `Basic ${b64}`
  }
}));

// Only report tasks in these statuses (the updatedAt filter already limits to tasks modified this week).
const ALLOWED_STATUSES = ['in progress', 'review', 'closed'];
// One response per role (assignee, accountable); dedupe by id.
const byId = new Map();
for (const item of $input.all()) {
  // OpenProject replies with application/hal+json, which n8n leaves as a raw string in `data`.
  const body = typeof item.json.data === 'string' ? JSON.parse(item.json.data) : item.json;
  for (const wp of body._embedded?.elements || []) {
    const status = (wp._links?.status?.title || '').toLowerCase();
    if (!ALLOWED_STATUSES.includes(status)) continue;
    if (!byId.has(wp.id)) {
      byId.set(wp.id, { id: wp.id, project: wp._links?.project?.title || 'Không rõ dự án', subject: wp.subject, status: wp._links?.status?.title || 'Unknown' });
    }
  }
}
// Sort by project then id so tasks of the same project sit together for the report.
const workPackages = [...byId.values()].sort((a, b) => a.project.localeCompare(b.project) || a.id - b.id);
return [{ json: { workPackages, count: workPackages.length, workPackagesJson: JSON.stringify(workPackages, null, 2) } }];

const lists = $input.all().map(i => i.json);
const target = lists.find(l => l.name === 'Kh\u00e1nh');
if (!target) {
  throw new Error("List 'Kh\u00e1nh' not found on board");
}
return [{ json: { listId: target.id } }];
